    """
    Optimized 3D convolution model using a custom CUDA kernel.
    The forward pass calls the custom `conv3d_cuda` operator defined via
    load_inline (compiled from C++ source).
    """
    def __init__(self, in_channels: int = 3,
                 out_channels: int = 64,
                 kernel_size: tuple = (3, 5, 7),
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, kernel_size,
                                stride=stride, padding=padding, dilation=dilation,
                                groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, width, height, depth).
        Returns:
            Output tensor after 3D convolution using the custom CUDA operator.
